<?php require_once "auth.php";require_once "../config/db.php";$msg="";if(isset($_POST['add'])){$n=trim($_POST['name']);$c=$_POST['category'];$price=(float)$_POST['price'];$stock=(int)$_POST['stock'];$d=trim($_POST['description']);$dos=trim($_POST['dosage']);$safe=trim($_POST['safety']);$rx=isset($_POST['rx'])?1:0;$img=trim($_POST['image_url']);$s=$conn->prepare("INSERT INTO products(name,category,price,stock_qty,description,dosage,safety_info,requires_prescription,image_url) VALUES(?,?,?,?,?,?,?,?,?)");$s->bind_param("ssdisssis",$n,$c,$price,$stock,$d,$dos,$safe,$rx,$img);$s->execute();$msg="Product added.";}if(isset($_GET['delete'])){$id=(int)$_GET['delete'];$conn->query("DELETE FROM products WHERE product_id=$id");header("Location: products.php");exit;}$r=$conn->query("SELECT * FROM products ORDER BY product_id DESC");?>
<?php include "../includes/header.php";?><div class="admin-nav"><div class="container"><a href="dashboard.php">Dashboard</a><a href="products.php">Products</a></div></div><main class="section"><div class="container"><div class="form-card"><h2>Add Product</h2><?php if($msg):?><div class="alert success"><?=$msg?></div><?php endif;?><form method="post"><div class="form-grid"><div class="field"><label>Name</label><input name="name" required></div><div class="field"><label>Category</label><select name="category"><option>Prescription Medicines</option><option>OTC Medicines</option><option>Wellness</option><option>Personal Care</option></select></div><div class="field"><label>Price</label><input type="number" step=".01" name="price" required></div><div class="field"><label>Stock</label><input type="number" name="stock" required></div><div class="field full"><label>Description</label><textarea name="description" required></textarea></div><div class="field"><label>Dosage</label><input name="dosage"></div><div class="field"><label>Safety Information</label><input name="safety"></div><div class="field full"><label>Image URL</label><input name="image_url" value="https://images.unsplash.com/photo-1584308666744-24d5c474f2ae?auto=format&fit=crop&w=700&q=80"></div><div class="field"><label><input type="checkbox" name="rx"> Requires prescription</label></div></div><button class="btn btn-primary" name="add">Add Product</button></form></div><div class="table-wrap"><table class="table"><tr><th>Product</th><th>Category</th><th>Price</th><th>Stock</th><th></th></tr><?php while($p=$r->fetch_assoc()):?><tr><td><?=htmlspecialchars($p['name'])?></td><td><?=htmlspecialchars($p['category'])?></td><td>LKR <?=number_format($p['price'],2)?></td><td><?=$p['stock_qty']?></td><td><a href="?delete=<?=$p['product_id']?>">Delete</a></td></tr><?php endwhile;?></table></div></div></main><?php include "../includes/footer.php";?>